// @ts-check
import { ConnectionType } from '../../utils/ConnectionType.js'
import { isNodejsRuntime, getRequire } from '../../utils/Runtime.js'
import { RuntimeName } from '../../utils/RuntimeName.js'
import { CommandDeserializer } from '../protocol/CommandDeserializer.js'
import { CommandSerializer } from '../protocol/CommandSerializer.js'
import { TransmitterWebsocketBrowser } from '../transmitter/TransmitterWebsocketBrowser.js'
import { TransmitterWebsocket } from '../transmitter/TransmitterWebsocket.js'
import { TransmitterHttp2 } from '../transmitter/TransmitterHttp2.js'
import { TransmitterHttp2Browser } from '../transmitter/TransmitterHttp2Browser.js'
import { Handler } from '../handler/Handler.js'
import { PluginRegistry, PluginPayloadBuilder } from '../../plugins/index.js'
import { Command } from '../../utils/Command.js'
import { CommandType } from '../../utils/CommandType.js'
import { WsConnectionData } from '../../utils/connectionData/WsConnectionData.js'
import { Http2ConnectionData } from '../../utils/connectionData/Http2ConnectionData.js'
import { InMemoryConnectionData } from '../../utils/connectionData/InMemoryConnectionData.js'

/**
 * @typedef {import('../../utils/connectionData/IConnectionData.js').IConnectionData} IConnectionData
 * @typedef {typeof import('../../types.d.ts').RuntimeName} RuntimeNameType
 */

/** @type {typeof import('../receiver/Receiver.js').Receiver} */
let _Receiver
/** @type {typeof import('../transmitter/Transmitter.js').Transmitter} */
let _Transmitter
/** @type {typeof import('../transmitter/TransmitterWebsocket.js').TransmitterWebsocket | typeof import('../transmitter/TransmitterWebsocketBrowser.js').TransmitterWebsocketBrowser} */
let _TransmitterWebsocket = isNodejsRuntime() ? TransmitterWebsocket : TransmitterWebsocketBrowser
/** @type {typeof import('../transmitter/TransmitterHttp2.js').TransmitterHttp2 | typeof import('../transmitter/TransmitterHttp2Browser.js').TransmitterHttp2Browser} */
let _TransmitterHttp2 = isNodejsRuntime() ? TransmitterHttp2 : TransmitterHttp2Browser

const requireDynamic = getRequire(import.meta.url)

export class Interpreter {
    /**
     * @param {string} runtimeContextId
     * @param {Command} command
     * @param {IConnectionData} connectionData
     * @returns {Promise<Command>}
     */
    static async execute(runtimeContextId, command, connectionData) {
        this.#logDebug('Command sent from calling side', command)

        if (PluginRegistry.arePluginsRegisteredForRuntime(runtimeContextId)) {
            const serializedPlugins = PluginPayloadBuilder.buildPluginsPayload(runtimeContextId)

            // Wrap the command with PluginWrapper
            command = new Command(command.runtimeName, CommandType.PluginWrapper, [
                serializedPlugins,
                command,
            ])
        }

        /** @type {Promise<Uint8Array> | Uint8Array | undefined} */
        let responseByteArray = undefined
        let messageByteArray = CommandSerializer.serialize(command, connectionData)
        if (!isNodejsRuntime() && connectionData.connectionType === ConnectionType.IN_MEMORY) {
            throw new Error('Nodejs Core Error: inMemory is only allowed in Nodejs runtime, not in browser')
        }

        if (connectionData instanceof WsConnectionData) {
            if (this.shouldEmbedHeadersInCommand(connectionData)) {
                command = this.wrapCommandWithContextMetadata(command, connectionData)
                messageByteArray = CommandSerializer.serialize(command, connectionData)
            }
            responseByteArray = await _TransmitterWebsocket.sendCommand(messageByteArray, connectionData)
        } else if (connectionData instanceof Http2ConnectionData) {
            responseByteArray = await _TransmitterHttp2.sendCommand(messageByteArray, connectionData)
        } else {
            const wrappedCommand = this.wrapCommandWithContextMetadata(command, connectionData)
            if (wrappedCommand !== command) {
                command = wrappedCommand
                messageByteArray = CommandSerializer.serialize(command, connectionData)
            }

            if (
                command.runtimeName === RuntimeName.Nodejs &&
                connectionData instanceof InMemoryConnectionData
            ) {
                if (!_Receiver) {
                    const { Receiver } = requireDynamic('../receiver/Receiver.js')
                    _Receiver = Receiver
                    if (!_Receiver) {
                        throw new Error('Nodejs Core Error: Receiver is undefined')
                    }
                }
                responseByteArray = await _Receiver.sendCommand(messageByteArray)
            } else {
                if (!_Transmitter) {
                    const { Transmitter } = requireDynamic('../transmitter/Transmitter.js')
                    _Transmitter = Transmitter
                    if (!_Transmitter) {
                        throw new Error('Nodejs Core Error: Transmitter is undefined')
                    }
                }

                responseByteArray = _Transmitter.sendCommand(messageByteArray, connectionData.getConfig())
            }
        }

        if (!responseByteArray) {
            throw new Error('No response received from Transmitter')
        }
        const responseCommand = CommandDeserializer.deserialize(responseByteArray)
        this.#logDebug('Command received on calling side', responseCommand)
        return responseCommand
    }

    /**
     *
     * @param {Uint8Array} messageByteArray
     * @returns {Promise<Command> | Command}
     */
    static process(messageByteArray) {
        const receivedCommand = CommandDeserializer.deserialize(messageByteArray)
        this.#logDebug('Command received on called side', receivedCommand)
        const responseCommand = Handler.handleCommand(receivedCommand)

        if (responseCommand instanceof Promise) {
            return responseCommand.then((resolvedResponse) => {
                this.#logDebug('Response sent from called side', resolvedResponse)
                return resolvedResponse
            })
        }

        this.#logDebug('Response sent from called side', responseCommand)
        return responseCommand
    }

    /**
     * @param {string} label
     * @param {unknown} details
     */
    static #logDebug(label, details) {
        try {
            const configuredValue = isNodejsRuntime()
                ? process.env.HYPERTUBE_DEBUG
                : Reflect.get(globalThis, 'HYPERTUBE_DEBUG')
            if (String(configuredValue).toLowerCase() !== 'true') {
                return
            }

            const message = `${label}: ${String(details)}`
            try {
                console.log(message)
            } catch {
                // Debug output must not affect interpreter behavior.
            }
            try {
                void import('../../sdk/tools/nodejs/MessageHelper.js')
                    .then(({ sendMessageToAppInsights }) => {
                        try {
                            sendMessageToAppInsights('SdkMessage', message)
                        } catch {
                            // Debug telemetry is best effort.
                        }
                    })
                    .catch(() => {})
            } catch {
                // Debug telemetry is best effort and must never be awaited.
            }
        } catch {
            // Debug logging must not affect interpreter behavior.
        }
    }

    /**
     * Browser WebSocket cannot attach custom HTTP upgrade headers, so headers are
     * embedded in the command payload via ContextMetadata instead.
     * @param {IConnectionData} connectionData
     * @returns {boolean}
     */
    static shouldEmbedHeadersInCommand(connectionData) {
        return (
            !isNodejsRuntime() &&
            connectionData instanceof WsConnectionData &&
            Object.keys(connectionData.getHeaders()).length > 0
        )
    }

    /**
     * @param {Command} command
     * @param {IConnectionData} connectionData
     * @returns {Command}
     */
    static wrapCommandWithContextMetadata(command, connectionData) {
        if (Object.keys(connectionData.getHeaders()).length === 0) {
            return command
        }

        const contextMetadataPayload = this.buildContextMetadataPayload(command, connectionData)
        return new Command(command.runtimeName, CommandType.ContextMetadata, [
            contextMetadataPayload,
            command,
        ])
    }

    /**
     * @param {Command} command
     * @param {IConnectionData} connectionData
     * @returns {Command}
     */
    static buildContextMetadataPayload(command, connectionData) {
        const metadataPayload = []
        const headers = connectionData.getHeaders()

        for (const key of Object.keys(headers)) {
            metadataPayload.push(key)
            metadataPayload.push(headers[key])
        }

        return new Command(command.runtimeName, CommandType.Array, metadataPayload)
    }
}
